theorem MIPRE.QLD.pAB_eq_linAB_of_isLinAB (hd : 1 ≤ d) {g : LowIndDegPoly (F := F) (m := 4 * m) (d := d)}
    (hg : IsLinAB g) (u₀ : Point F (4 * m)) :
    pAB g u₀ = linAB hd ((gA hd g).eval u₀) ((gB hd g).eval u₀) := by sorry

theorem MIPRE.QLD.isGood_of (hd : 1 ≤ d) {g : LowIndDegPoly (F := F) (m := 4 * m) (d := d)}
    (hlin : IsLinAB g) (hA : ¬ (gA hd g).DepOutside xSet) (hB : ¬ (gB hd g).DepOutside zSet) :
    IsGood g := by sorry
